async function mineOne(orePattern){
  const start = Date.now();
  let attempts = 0;
  while(Date.now() - start < 15000){
    const rock = sdk.findNearbyLoc(orePattern);
    if(!rock){ console.log('no rock', orePattern); await sdk.waitForTicks(2); continue; }
    console.log(`trying to mine ${rock.name} at ${rock.x},${rock.z} id=${rock.id}`);
    const res = await bot.interactLoc(rock, 'Mine');
    console.log('mine res', res);
    console.log('inv', sdk.getInventory().map(i=>i.name));
    console.log('mining xp', sdk.getSkill('mining')?.experience);
    if(res.success && sdk.getInventory().some(i=>/ore/i.test(i.name))){
      console.log('got ore, took', Date.now()-start, 'ms');
      return true;
    }
    // also check waitForCondition style
    await sdk.waitForTicks(1);
    attempts++;
    if(attempts>5){ console.log('too many attempts'); break; }
  }
  return false;
}
