    while(Date.now()-start < 15000){
      const pos = sdk.getState().player;
      if(Math.hypot(pos.worldX-x, pos.worldZ-z) < 5) break;
      await sdk.waitForTicks(3);
    }
    console.log('arrived at', sdk.getState().player.worldX, sdk.getState().player.worldZ);
    await sdk.waitForTicks(2);
  }
}
