// Check magic XP needed for next levels
// Use wiki or estimate via OSRS formula
// OSRS XP for level L: sum_{i=1}^{L-1} floor(i+300*2^{i/7})/4
// Let's compute quickly
function xpForLevel(level){
  let xp=0;
  for(let i=1;i<level;i++){
    xp+=Math.floor(i + 300*Math.pow(2,i/7));
  }
  return Math.floor(xp/4);
}
